async def act(page):
    import re
    import io
    import csv
    from datetime import datetime

    # Evaluate knowledge-base helpers for this task:
    # - get_dashboard_summary, generate_sales_summary_for_date_range, export_dashboard_snapshot,
    #   download_revenue_and_orders_report, export_revenue_and_orders
    #   * These helpers operate on dashboard widgets or return compact recent-orders CSVs (usually
    #     the "Last 5 Orders" widget) and revenue summaries. None provide a full Sales Orders CSV
    #     across arbitrary historical months. Therefore they are not suitable for computing a
    #     month-by-month count for Feb..Nov 2022, and we will not call them.

    # Helper: try parsing several common Magento-export date formats
    def try_parse_date(s: str):
        if not s:
            return None
        s = s.strip()
        if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
            s = s[1:-1]
        fmts = [
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y",
            "%Y/%m/%d %H:%M:%S",
            "%Y/%m/%d",
            "%b %d, %Y %H:%M:%S",
            "%b %d, %Y",
            "%B %d, %Y %H:%M:%S",
            "%B %d, %Y",
        ]
        for f in fmts:
            try:
                return datetime.strptime(s, f)
            except Exception:
                continue
        try:
            return datetime.fromisoformat(s)
        except Exception:
            return None

    # Derive base origin from the current page URL so we can try candidate export endpoints
    m = re.match(r"^(https?://[^/]+)", page.url or "")
    if not m:
        raise RuntimeError("Unable to determine base origin from current page URL")
    base = m.group(1)

    # Candidate Magento export endpoints (try several common variants)
    candidates = [
        f"{base}/index.php/admin/sales_order/exportCsv/",
        f"{base}/index.php/admin/sales_order/exportCsv",
        f"{base}/index.php/admin/sales_order/exportCsv/index/",
        f"{base}/admin/sales_order/exportCsv/",
        f"{base}/admin/sales_order/exportCsv",
    ]

    content = None

    # Try direct GET requests first; page.request reuses browser context cookies/session
    for url in candidates:
        try:
            resp = await page.request.get(url)
        except Exception:
            resp = None
        if resp is not None and resp.status == 200:
            try:
                content = await resp.text()
            except Exception:
                content = None
        if content:
            break

    # If direct endpoints didn't return CSV, navigate to the Sales Orders grid (relative goto) to provide context
    if not content:
        try:
            await page.goto('/index.php/admin/sales_order/index/')
            await page.wait_for_timeout(1000)
        except Exception:
            # ignore navigation errors and still attempt endpoints
            pass

        for url in candidates:
            try:
                resp = await page.request.get(url)
            except Exception:
                resp = None
            if resp is not None and resp.status == 200:
                try:
                    content = await resp.text()
                except Exception:
                    content = None
            if content:
                break

    if not content:
        # As a last-ditch attempt, try to locate an Export link/button on the page and click it to initialize export
        # (clicking may navigate away; we will click only if it seems safe and then retry endpoints). This is optional
        # and conservative.
        try:
            # Look for an export link or button via accessible roles
            loc_link = None
            try:
                loc_link = page.get_by_role('link', name=re.compile('Export', re.I))
            except Exception:
                loc_link = None
            loc_button = None
            try:
                loc_button = page.get_by_role('button', name=re.compile('Export', re.I))
            except Exception:
                loc_button = None

            clicked = False
            if loc_link is not None:
                try:
                    if await loc_link.count() > 0:
                        # clicking a link likely navigates away; make it last action if we choose to click.
                        await loc_link.first.click()
                        clicked = True
                        await page.wait_for_timeout(800)
                except Exception:
                    clicked = False
            if not clicked and loc_button is not None:
                try:
                    if await loc_button.count() > 0:
                        await loc_button.first.click()
                        clicked = True
                        await page.wait_for_timeout(800)
                except Exception:
                    clicked = False

            if clicked:
                for url in candidates:
                    try:
                        resp = await page.request.get(url)
                    except Exception:
                        resp = None
                    if resp is not None and resp.status == 200:
                        try:
                            content = await resp.text()
                        except Exception:
                            content = None
                    if content:
                        break
        except Exception:
            pass

    if not content:
        raise RuntimeError('Unable to retrieve orders CSV export from the admin. Tried multiple endpoints and fallbacks.')

    # Normalize BOM
    content = content.lstrip('\ufeff')

    # Parse CSV content
    stream = io.StringIO(content)
    reader = csv.reader(stream)
    try:
        header = next(reader)
    except StopIteration:
        raise RuntimeError('CSV export was empty')

    header_lc = [h.lower() for h in header]
    created_idx = None
    status_idx = None

    # Heuristics to locate date and status columns
    for i, h in enumerate(header_lc):
        if any(k in h for k in ('created at', 'created', 'created_at', 'order date', 'order_date', 'date')):
            if created_idx is None:
                created_idx = i
        if 'status' in h:
            status_idx = i

    if created_idx is None:
        raise RuntimeError(f"Couldn't find a created/date column in CSV header: {header}")

    successful_statuses = {"complete", "processing", "closed"}

    # Initialize counts for months 2..11 (Feb..Nov)
    counts = {m: 0 for m in range(2, 12)}

    for row in reader:
        if len(row) <= created_idx:
            continue
        created_raw = row[created_idx]
        dt = try_parse_date(created_raw)
        if not dt:
            continue
        if dt.year != 2022:
            continue
        if dt.month < 2 or dt.month > 11:
            continue
        if status_idx is not None and status_idx < len(row):
            status_raw = (row[status_idx] or "").strip().lower()
            if not status_raw:
                continue
            if any(s in status_raw for s in successful_statuses):
                counts[dt.month] += 1
        else:
            # No status column present: conservatively count the order
            counts[dt.month] += 1

    # Print lines in MM:COUNT format for months 02..11
    out_lines = [f"{m:02d}:{counts.get(m,0)}" for m in range(2, 12)]
    print("\n".join(out_lines))

